import {chunks,isCorrect,recordAttempt,removeGroup,drop} from './rules.js';
import {initScene} from './scene.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='word-island-3d-v1',VERSION=1;
const names=['欢迎乐园','博物馆奇遇','自然建造营','Unit 3 练习站','Unit 4 练习站','Unit 5 练习站','Unit 6 练习站','Unit 7 练习站','Unit 8 练习站','Unit 9 练习站'];
const icons=['🎡','🏛️','🌲','🏡','🚂','🌤️','⚖️','🎻','🧭','🗺️'];
const descriptions=['坐上摩天轮，开启你的第一场单词探险。','走进小小博物馆，让每个新单词都有故事。','在森林里搭建营地，让知识和小树一起长大。'];
let data,ui={unit:0,group:0,index:0,mode:'learn',hinted:false,solved:false,letters:[],selected:[],match:null},scene,matchTimer,toastTimer;
let save={version:VERSION,stars:0,words:{},matchBest:0,unit:0,group:0};
try{const parsed=JSON.parse(localStorage.getItem(KEY));if(validSave(parsed))save={...save,...parsed}}catch{}
function validSave(p){return p&&p.version===1&&Number.isFinite(p.stars)&&p.stars>=0&&p.stars<1e9&&p.words&&typeof p.words==='object'&&!Array.isArray(p.words)&&Object.keys(p.words).length<5000&&Object.values(p.words).every(v=>v&&typeof v==='object'&&['seen','listening','assembly','independent','hinted','errors'].every(k=>v[k]===undefined||(Number.isFinite(v[k])&&v[k]>=0&&v[k]<1e9)))}
function persist(){save.unit=ui.unit;save.group=ui.group;try{localStorage.setItem(KEY,JSON.stringify(save))}catch{toast('浏览器无法保存进度，请在家长进度中导出备份。')}updateRewards()}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
const unit=()=>data.units[ui.unit],groups=()=>chunks(unit().entries),words=()=>groups()[ui.group]||[],word=()=>words()[ui.index],matchWords=()=>[...new Map(words().map(w=>[w.en.toLowerCase(),w])).values()];
function stat(w){return save.words[w.id]||{}}
function updateRewards(){$('#stars').textContent=save.stars;$('#companion-level').textContent=save.stars>=30?'小兔 · 勇敢探险家':save.stars>=10?'小兔 · 默契好伙伴':'小兔 · 初次见面';$('#reward-note').textContent=save.stars>=30?'⚑ 小岛装饰全解锁，继续收集知识吧！':save.stars>=15?'✿ 已有花丛和彩旗，30 颗星解锁更多惊喜':save.stars>=5?'✿ 花丛已盛开，15 颗星迎来彩旗':'✿ 收集 5 颗星，给小岛添一丛花';scene?.setProgress(save.stars)}
function award(mode,correct){const w=word(),before=stat(w),key=mode==='spell'?(ui.hinted?'hinted':'independent'):{learn:'seen',listen:'listening',assemble:'assembly'}[mode];save.words[w.id]=recordAttempt(before,mode,correct,ui.hinted);if(correct&&!(before[key]>0)){save.stars+=mode==='spell'&&!ui.hinted?3:1;toast(mode==='spell'&&!ui.hinted?'✦ 独立拼写成功！收下 3 颗星':'✦ 又进步了一点，收下 1 颗星')}persist();renderCards()}
function speak(text,onComplete=()=>{}){if(!('speechSynthesis'in window)||typeof SpeechSynthesisUtterance==='undefined'){toast('当前浏览器没有朗读功能，可以先练习认识、拼搭和默写。');return false}const english=speechSynthesis.getVoices().filter(v=>v.lang.startsWith('en'));if(!english.length){toast('未找到英语朗读声音。请在系统中启用英语语音后再试。');return false}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=.78;utterance.voice=english.find(v=>v.lang==='en-US')||english[0];utterance.onend=()=>onComplete(true);utterance.onerror=()=>{onComplete(false);toast('这次朗读没有成功，请检查设备语音设置。')};speechSynthesis.speak(utterance);return true}
function stopMatch(){clearInterval(matchTimer);matchTimer=null;if(ui.match)ui.match.running=false}
function resetQuestion(){ui.hinted=false;ui.solved=false;ui.selected=[];ui.letters=[];if('speechSynthesis'in window)speechSynthesis.cancel()}
function navigateUnit(i){stopMatch();ui.unit=i;ui.group=0;ui.index=0;ui.match=null;resetQuestion();persist();renderAll();scene?.setUnit(i);scene?.setProgress(save.stars)}
function navigateGroup(delta){const next=ui.group+delta;if(next<0||next>=groups().length)return;stopMatch();ui.group=next;ui.index=0;ui.match=null;resetQuestion();persist();renderAll()}
function renderNav(){$('#unit-nav').innerHTML=data.units.map((u,i)=>`<button class="unit-link ${ui.unit===i?'active':''}" data-unit="${i}" aria-current="${ui.unit===i?'page':'false'}"><span class="unit-icon">${icons[i]||'🌱'}</span><span><b>${names[i]||esc(u.label)}</b><small>${i<3?'3D 场景探索':'通用单词练习'}</small></span><span class="arrow">›</span></button>`).join('');$('#unit-nav').querySelectorAll('button').forEach(b=>b.onclick=()=>navigateUnit(+b.dataset.unit))}
function renderAll(){renderNav();$('#crumb').textContent=names[ui.unit]||unit().label;$('#unit-title').textContent=ui.unit===0?'今天，去乐园学单词吧！':names[ui.unit];$('#unit-description').textContent=descriptions[ui.unit]||'本单元开放全部单词通用练习；专属 3D 场景还在建设中。';$('#world-label').textContent=scene?.is3D===false?'2D 展示 · 单词练习可用':ui.unit<3?`${names[ui.unit]} · 3D 探索`:'小岛练习营 · 通用场景';$('#group-label').textContent=`第 ${ui.group+1} / ${groups().length} 组`;$('#group-count').textContent=`本组 ${words().length} 个词`;$('#unit-total').textContent=`${unit().label} · 共 ${unit().entries.length} 个词条 · 按原顺序每 5 个一组`;$('#prev-group').disabled=ui.group===0;$('#next-group').disabled=ui.group===groups().length-1;renderCards();renderPractice();updateRewards()}
function renderCards(){$('#word-cards').innerHTML=words().map((w,i)=>`<button class="word-card ${i===ui.index?'active':''}" data-index="${i}" aria-label="${ui.mode==='learn'?'练习 '+esc(w.en):'选择第 '+(i+1)+' 个练习'}"><span class="word-number">${String(ui.group*5+i+1).padStart(2,'0')}</span><span class="badge">${stat(w).independent?'✦':stat(w).hinted?'♡':stat(w).seen?'✓':''}</span><strong>${ui.mode==='learn'?esc(w.displayEn||w.en):'单词 '+String(i+1).padStart(2,'0')}</strong><small>${ui.mode==='learn'?esc(w.zh):'训练中，答案已收起'}</small></button>`).join('');$('#word-cards').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(ui.mode==='match'){stopMatch();ui.mode='learn'}ui.index=+b.dataset.index;resetQuestion();renderCards();renderPractice();scene?.focusWord(word().en)})}
function feedback(text,error=false){const f=$('#feedback');if(f){f.textContent=text;f.classList.toggle('error',error)}}
function nextWord(){ui.index=(ui.index+1)%words().length;resetQuestion();renderCards();renderPractice()}
function renderPractice(){if(ui.mode!=='learn'){$('#scene-note').textContent='专心挑战，场景词语提示已收起';$('#toast').classList.remove('show')}else $('#scene-note').textContent='轻点小岛上的物件，发现惊喜';document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===ui.mode);b.setAttribute('aria-selected',String(b.dataset.mode===ui.mode))});const w=word(),container=$('#practice');if(!w){container.innerHTML='<p>这个单元暂时没有词条。</p>';return}const top=`<div class="prompt-top"><span>${ui.mode==='learn'?'发现一个新朋友':ui.mode==='listen'?'听一听，选择你听到的词':ui.mode==='assemble'?'把字母排成正确顺序':'看中文，自己写出英文'}</span><span>${ui.index+1} / ${words().length}</span></div>`;if(ui.mode==='match'){renderMatch();return}let content='';if(ui.mode==='learn'){content=`<div class="word-prompt"><div class="big-word">${esc(w.displayEn||w.en)}</div><div class="translation"><span class="word-pos">${esc(w.pos)}</span>${esc(w.zh)}</div></div><button class="listen-button" id="speak" aria-label="朗读 ${esc(w.en)}">♪</button><div class="button-row"><button class="primary" id="learned">认识啦，下一词 →</button></div><div class="hint">听一听 · 读一读 · 在心里想一幅画</div>`}else if(ui.mode==='listen'){const uniqueAlternatives=[...new Map(unit().entries.filter(x=>x.en!==w.en).map(x=>[x.en,x])).values()];const alternatives=[w,...shuffle(uniqueAlternatives).slice(0,3)];ui.options=shuffle(alternatives);content=`<div class="word-prompt"><button class="listen-button" id="speak" aria-label="播放目标词">♪</button><div class="translation">点击播放，再选一个</div></div><div class="choices">${ui.options.map((x,i)=>`<button class="choice" data-answer="${i}">${esc(x.en)}</button>`).join('')}</div><div class="feedback" id="feedback" aria-live="polite"></div><div class="button-row"><button class="secondary" id="skip">换一个词 →</button></div><div class="hint">需要设备支持英语朗读；听选记录与默写分开。</div>`}else if(ui.mode==='assemble'){ui.letters=shuffle([...w.en].map((letter,i)=>({letter,id:i})));content=`<div class="word-prompt"><div class="big-word" style="font-size:23px">${esc(w.zh)}</div><div class="translation">${esc(w.pos)} · ${w.en.length} 个字符（含空格）</div></div><div class="letter-slots" id="letter-slots" aria-live="polite">…</div><div class="letters">${ui.letters.map((x,i)=>`<button data-letter="${i}" aria-label="${x.letter===' '?'空格':esc(x.letter)}">${x.letter===' '?'␣':esc(x.letter)}</button>`).join('')}</div><div class="button-row"><button class="secondary" id="undo">撤回</button><button class="primary" id="check-assembly">拼好啦</button></div><div class="feedback" id="feedback" aria-live="polite"></div>`}else{content=`<div class="word-prompt"><div class="big-word" style="font-size:25px">${esc(w.zh)}</div><div class="translation">${esc(w.pos)} · 不看英文，试试看</div></div><form id="spell-form"><input class="spell-input" id="spell-input" aria-label="输入英文单词或短语" placeholder="在这里写英文" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false"><div class="button-row"><button type="button" class="secondary" id="hint-button">需要提示 ♡</button><button class="primary" type="submit">检查答案 →</button></div></form><div class="feedback" id="feedback" aria-live="polite"></div><div class="hint" id="hint-line">独立拼写才点亮 ✦；使用提示会单独记录。</div>`}container.innerHTML=top+content;
const speakButton=$('#speak');if(speakButton)speakButton.onclick=()=>{ui.audioPlayed=false;const questionID=w.id;const ok=speak(w.en,success=>{if(ui.mode==='listen'&&word().id===questionID)ui.audioPlayed=success});if(ui.mode==='listen'){if(!ok)feedback('朗读不可用，这次不会记为听选练习。',true)}};
if(ui.mode==='learn')$('#learned').onclick=()=>{award('learn',true);nextWord()};
if(ui.mode==='listen'){ui.audioPlayed=false;$('#skip').onclick=nextWord;container.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(ui.solved)return;if(!ui.audioPlayed){feedback('请先点击 ♪ 听一听，再选择。',true);return}const correct=ui.options[+b.dataset.answer].en===w.en;award('listen',correct);b.classList.add(correct?'correct':'wrong');if(correct){ui.solved=true;feedback('听得真仔细！');$('#skip').textContent='下一词 →'}else feedback('再听一次，不着急。',true)})}
if(ui.mode==='assemble'){container.querySelectorAll('[data-letter]').forEach(b=>b.onclick=()=>{if(ui.solved||b.classList.contains('used'))return;ui.selected.push(+b.dataset.letter);b.classList.add('used');$('#letter-slots').textContent=ui.selected.map(i=>ui.letters[i].letter===' '?'␣':ui.letters[i].letter).join('')});$('#undo').onclick=()=>{if(ui.solved)return;const i=ui.selected.pop();if(i!==undefined)container.querySelector(`[data-letter="${i}"]`).classList.remove('used');$('#letter-slots').textContent=ui.selected.map(i=>ui.letters[i].letter===' '?'␣':ui.letters[i].letter).join('')||'…'};$('#check-assembly').onclick=()=>{if(ui.solved){nextWord();return}const correct=isCorrect(ui.selected.map(i=>ui.letters[i].letter).join(''),w.en);award('assemble',correct);feedback(correct?'拼搭成功！这个成绩记在「拼搭」，继续挑战默写吧。':'还差一点，试试撤回再拼。',!correct);if(correct){ui.solved=true;$('#check-assembly').textContent='下一词 →'}}}
if(ui.mode==='spell'){$('#hint-button').onclick=()=>{ui.hinted=true;$('#hint-line').textContent=`提示：${w.en}。这次将记为「提示后拼写」。`;$('#hint-button').textContent='已使用提示';$('#spell-input').focus()};$('#spell-form').onsubmit=e=>{e.preventDefault();if(ui.solved){nextWord();return}const answer=$('#spell-input').value;if(!answer.trim()){feedback('先写下你的答案吧。',true);return}const correct=isCorrect(answer,w.en);award('spell',correct);feedback(correct?(ui.hinted?'写对啦！下次试着不看提示吧。':'独立拼写成功！你真的记住了一次。'):'还没写对，可以再试一次，或点击提示。',!correct);if(correct){ui.solved=true;$('#spell-input').readOnly=true;$('#spell-form button[type="submit"]').textContent='下一词 →';$('#hint-button').disabled=true}}}
}
function shuffle(a){const r=[...a];for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]]}return r}
function newMatch(){stopMatch();const board=Array(35).fill(null),pool=matchWords();for(let y=4;y<7;y++)for(let x=0;x<5;x++)board[y*5+x]=(x+y)%pool.length;board[30]=board[31]=board[32]=0;ui.match={board,score:0,running:false,over:false,drops:0};renderMatch()}
function toggleMatch(){if(!ui.match)newMatch();if(ui.match.over){newMatch();return}if(ui.match.running){stopMatch();renderMatch();return}ui.match.running=true;matchTimer=setInterval(()=>{if(document.hidden||$('#modal').open)return;const available=[];for(let c=0;c<5;c++)if(ui.match.board[c]==null)available.push(c);if(!available.length){endMatch();return}const column=available[Math.floor(Math.random()*available.length)],value=Math.floor(Math.random()*matchWords().length),result=drop(ui.match.board,column,value);ui.match.board=result.board;ui.match.drops++;if(result.full)endMatch();else renderMatch()},4000);renderMatch()}
function endMatch(){stopMatch();ui.match.over=true;save.matchBest=Math.max(save.matchBest||0,ui.match.score);persist();renderMatch()}
function renderMatch(){const m=ui.match;$('#practice').innerHTML=`<div class="match-toolbar"><span>连接 3 个或更多相同英文</span><b>${m?.score||0} 分</b></div><div class="match-board" role="group" aria-label="单词消消乐棋盘">${(m?.board||Array(35).fill(null)).map((v,i)=>`<button class="match-cell ${v==null?'empty':'c'+v}" data-cell="${i}" ${v==null?'disabled':''} aria-label="第 ${Math.floor(i/5)+1} 行，第 ${i%5+1} 列，${v==null?'空':esc(matchWords()[v]?.en)}">${v==null?'':esc(matchWords()[v]?.en)}</button>`).join('')}</div>${m?.over?'<div class="match-overlay">棋盘满啦！休息一下，再来一局吧。</div>':''}<div class="button-row"><button class="primary" id="match-toggle">${!m?'开始游戏':m.over?'重新准备':m.running?'暂停一下':'继续游戏'}</button><button class="secondary" id="match-new">新一局</button></div><div class="hint left">上下左右相连的同词 ≥3 个才能消除；上方词块会落下。每 4 秒掉落一块，填满就结束。消除积分不计为拼写掌握。</div><div class="feedback" id="feedback" aria-live="polite"></div>`;
$('#match-toggle').onclick=()=>{if(!ui.match){newMatch();toggleMatch()}else toggleMatch()};$('#match-new').onclick=()=>{if(ui.match?.running&&!confirm('结束这一局并重新开始？本局分数不会继续。'))return;newMatch()};$('#practice').querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{if(!ui.match?.running){feedback('先点击开始或继续，再消除单词。');return}const result=removeGroup(ui.match.board,+b.dataset.cell);if(!result.removed){feedback('找找上下左右相连的 3 个相同单词。');return}ui.match.board=result.board;ui.match.score+=result.removed*10;save.matchBest=Math.max(save.matchBest||0,ui.match.score);persist();renderMatch();feedback(`消除了 ${result.removed} 个词块！`)})}
function openModal(title,html){if(ui.match?.running){stopMatch();renderMatch()}$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;$('#modal').showModal()}
function openMap(){openModal('下一站，去哪里？',`<p class="hint left">前三站可以探索专属 3D 场景，所有单元都可直接练习。</p><div class="map-grid">${data.units.map((u,i)=>`<button class="map-tile" data-map-unit="${i}"><span>${icons[i]}</span><div><b>${names[i]}</b><small>${u.entries.length} 个词条 · ${i<3?'3D 场景开放':'通用练习开放'}</small></div></button>`).join('')}</div>`);$('#modal-content').querySelectorAll('[data-map-unit]').forEach(b=>b.onclick=()=>{$('#modal').close();navigateUnit(+b.dataset.mapUnit)})}
function openParent(){const all=data.units.flatMap(u=>u.entries),count=k=>all.filter(w=>stat(w)[k]>0).length;openModal('每一小步，都看得见',`<p class="hint left">只记录当前浏览器的练习结果。独立拼写表示至少独立答对一次，不等同于长期掌握。拼搭、提示后拼写和消除积分分别统计。</p><div class="stats-grid"><div class="stat"><b>${count('seen')}</b><span>已认识词条</span></div><div class="stat"><b>${count('listening')}</b><span>听选答对词条</span></div><div class="stat"><b>${count('independent')}</b><span>独立拼写词条</span></div><div class="stat"><b>${count('hinted')}</b><span>提示后拼写词条</span></div></div><p class="hint left">拼搭答对：${count('assembly')} 个词条 · 消除最高分：${save.matchBest||0} · 星星：${save.stars}</p>${data.units.map(u=>{const n=u.entries.filter(w=>stat(w).independent>0).length;return `<div class="progress-row"><div><b>${esc(u.label)}</b><span>${n} / ${u.entries.length} 独立拼写</span></div><div class="progress-bar"><i style="width:${n/u.entries.length*100}%"></i></div><p class="progress-meta">听选 ${u.entries.filter(w=>stat(w).listening>0).length} · 拼搭 ${u.entries.filter(w=>stat(w).assembly>0).length} · 提示后拼写 ${u.entries.filter(w=>stat(w).hinted>0).length}</p></div>`}).join('')}<div class="button-row"><button class="primary" id="export">导出进度备份</button><button class="secondary" id="import-trigger">导入小岛备份</button><input id="import" type="file" accept="application/json,.json" hidden><button class="secondary danger" id="reset">清空本机进度</button></div><p class="hint left">这是独立的新存档，仅支持本游戏导出的 JSON 文件；尚未实现旧游戏存档迁移。导入会替换当前进度，建议先导出备份。不上传文件，也不保存姓名、年龄、录音或账户信息。</p>`);$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({...save,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='word-island-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已准备下载进度备份。')};$('#import-trigger').onclick=()=>$('#import').click();$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2000000){toast('备份文件过大，请选择本游戏导出的 JSON。');return}try{const parsed=JSON.parse(await file.text());if(!validSave(parsed))throw Error();const allowed=new Set(all.map(w=>w.id));if(Object.keys(parsed.words).some(k=>!allowed.has(k)))throw Error();if(!confirm('导入将替换当前小岛进度。确定继续吗？'))return;save={version:1,stars:parsed.stars,words:parsed.words,matchBest:Number.isFinite(parsed.matchBest)?Math.max(0,parsed.matchBest):0,unit:0,group:0};persist();renderCards();openParentAfterClose();toast('进度导入成功。')}catch{toast('无法识别这个备份。请使用本游戏导出的进度文件。')}};$('#reset').onclick=()=>{if(!confirm('确定清空这台设备上的所有单词探险岛进度？建议先导出备份。'))return;save={version:1,stars:0,words:{},matchBest:0,unit:0,group:0};persist();renderCards();openParentAfterClose();toast('已清空本机进度，可以重新出发。')}}
function openParentAfterClose(){$('#modal').close();openParent()}
$('#modal-close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}};
$('#prev-group').onclick=()=>navigateGroup(-1);$('#next-group').onclick=()=>navigateGroup(1);$('#map-button').onclick=openMap;$('#parent-button').onclick=openParent;$('#parent-header-button').onclick=openParent;$('#scene-reset').onclick=()=>{scene?.setUnit(ui.unit);scene?.setProgress(save.stars);toast('回到小岛的最佳观景点。')};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{stopMatch();ui.mode=b.dataset.mode;resetQuestion();renderCards();renderPractice()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&ui.match?.running){stopMatch();renderMatch()}});window.addEventListener('pagehide',event=>{stopMatch();if(event.persisted){if(ui.mode==='match')renderMatch()}else scene?.dispose()});window.addEventListener('pageshow',event=>{if(event.persisted){updateRewards();if(ui.mode==='match')renderMatch()}});
async function start(){try{const response=await fetch('./vocabulary.json');if(!response.ok)throw Error('vocabulary');data=await response.json();if(!data.units?.length)throw Error('vocabulary');ui.unit=Math.min(Math.max(0,Number.isInteger(save.unit)?save.unit:0),data.units.length-1);ui.group=Math.min(Math.max(0,Number.isInteger(save.group)?save.group:0),groups().length-1);renderAll();scene=await initScene($('#scene'),label=>{if(ui.mode!=='learn')return;$('#scene-note').textContent=label;toast(label)});scene.setUnit(ui.unit);scene.setProgress(save.stars);if(scene.is3D===false)$('#world-label').textContent='2D 展示 · 单词练习可用';if('speechSynthesis'in window)speechSynthesis.getVoices()}catch(error){console.error(error);$('#practice').innerHTML='<p class="feedback error">小岛加载遇到问题，请刷新页面再试。若仍不可用，请检查词库文件和浏览器支持。</p>';toast('加载未完成，请刷新页面再试。')}}
start();
